diff --git a/lib/illustration-generation.ts b/lib/illustration-generation.ts
new file mode 100644
index 0000000..c7824ad
--- /dev/null
+++ b/lib/illustration-generation.ts
@@ -0,0 +1,267 @@
+'use client';
+
+import { RequestStatus } from '@prisma/client';
+
+import createLogger from '@/lib/logger';
+import { getCurrentUserIsBanned } from '@/data/user';
+import { isGeminiModel } from '@/constants/image';
+import {
+  GeminiAspectRatio,
+  ImageGenerationData,
+  ImageGenerationMode
+} from '@/types/image-generation';
+import {
+  ImageGenerationWithOutputUrl,
+  getImageGenerationById
+} from '@/data/image-generation';
+import { imageGenGemini } from '@/lib/client/image-generation';
+
+import { generateWithComfyUI } from './comfyui';
+
+const logger = createLogger('illustration-generation');
+
+/**
+ * 驗證 illustration 模式的生成請求
+ * 檢查用戶是否被禁用
+ */
+async function validateIllustrationGeneration(): Promise<void> {
+  try {
+    const { isBanned, releaseAt } = await getCurrentUserIsBanned();
+    if (isBanned) {
+      throw new Error(
+        'User is banned from generating images until ' + releaseAt
+      );
+    }
+  } catch (error) {
+    if (error instanceof Error && error.message.includes('banned')) {
+      throw error;
+    }
+    throw new Error('Failed to verify ban status');
+  }
+}
+
+/**
+ * 處理 illustration 模式的 inputImage
+ * 返回處理後的 inputImage 物件或 undefined
+ */
+async function processInputImageForIllustration(
+  payload: ImageGenerationData
+): Promise<{ id: string } | undefined> {
+  let inputImage: { id: string } | undefined;
+
+  // 如果已經有 inputImageId，直接使用
+  if (payload.inputImageId) {
+    inputImage = { id: payload.inputImageId };
+    logger.info('Using existing input image ID', {
+      inputImageId: payload.inputImageId
+    });
+
+    // 如果 inputImage 是 URL，需要轉換為 base64 供 RunPod 使用
+    if (payload.inputImage) {
+      const isHttpUrl =
+        payload.inputImage.startsWith('http://') ||
+        payload.inputImage.startsWith('https://');
+      if (isHttpUrl) {
+        logger.info(
+          'Converting URL to base64 for RunPod (skipping S3 upload)',
+          {
+            url: payload.inputImage.substring(0, 100)
+          }
+        );
+
+        const imageResponse = await fetch(payload.inputImage);
+        if (!imageResponse.ok) {
+          throw new Error('Failed to fetch image from URL');
+        }
+        const blob = await imageResponse.blob();
+        const arrayBuffer = await blob.arrayBuffer();
+        const base64 = Buffer.from(arrayBuffer).toString('base64');
+        const mimeType = blob.type || 'image/png';
+        const base64DataUrl = `data:${mimeType};base64,${base64}`;
+
+        // 替換 URL 為 base64 供 RunPod 使用
+        payload.inputImage = base64DataUrl;
+      }
+    }
+  } else if (payload.inputImage) {
+    const isHttpUrl =
+      payload.inputImage.startsWith('http://') ||
+      payload.inputImage.startsWith('https://');
+
+    if (isHttpUrl) {
+      // 如果是 URL，獲取圖片並轉換為 base64 上傳
+      logger.warn(
+        'inputImage is a URL but no inputImageId provided - fetching and re-uploading',
+        {
+          url: payload.inputImage.substring(0, 100)
+        }
+      );
+
+      const imageResponse = await fetch(payload.inputImage);
+      if (!imageResponse.ok) {
+        throw new Error('Failed to fetch image from URL');
+      }
+      const blob = await imageResponse.blob();
+      const arrayBuffer = await blob.arrayBuffer();
+      const base64 = Buffer.from(arrayBuffer).toString('base64');
+      const mimeType = blob.type || 'image/png';
+      const base64DataUrl = `data:${mimeType};base64,${base64}`;
+
+      // 替換 URL 為 base64 供 RunPod 使用
+      payload.inputImage = base64DataUrl;
+
+      const response = await fetch('/api/image/base64', {
+        method: 'POST',
+        headers: {
+          'Content-Type': 'application/json'
+        },
+        body: JSON.stringify({ base64Image: base64DataUrl })
+      });
+
+      if (!response.ok) {
+        throw new Error('Failed to upload image fetched from URL');
+      }
+
+      inputImage = await response.json();
+    } else {
+      // 原始 base64 上傳流程（data: URL 或原始 base64）
+      const response = await fetch('/api/image/base64', {
+        method: 'POST',
+        headers: {
+          'Content-Type': 'application/json'
+        },
+        body: JSON.stringify({ base64Image: payload.inputImage })
+      });
+
+      if (!response.ok) {
+        throw new Error('Failed to upload base64 image');
+      }
+
+      inputImage = await response.json();
+    }
+  }
+
+  return inputImage;
+}
+
+/**
+ * 使用 Gemini API 生成 illustration 模式的圖片
+ */
+async function generateIllustrationWithGemini(
+  payload: ImageGenerationData,
+  inputImage: { id: string } | undefined
+): Promise<ImageGenerationWithOutputUrl> {
+  logger.info('[TEST] generateIllustrationWithGemini 開始', {
+    hasInputImage: !!inputImage,
+    modelName: payload.baseModel
+  });
+  // 決定 Gemini 的生成類型
+  const geminiType = ImageGenerationMode.illustration;
+
+  logger.info('[TEST] 調用 imageGenGemini', {
+    type: geminiType,
+    modelName: payload.baseModel
+  });
+
+  // Note: 插畫生成的圖片預設是正方形
+  const geminiResult = await imageGenGemini({
+    type: geminiType,
+    prompt: payload.prompt,
+    inputImages: inputImage ? [{ id: inputImage.id }] : undefined,
+    modelName: payload.baseModel || undefined,
+    aspectRatio: GeminiAspectRatio.SQUARE
+  });
+
+  // 如果生成失敗，拋出包含 errorCode 的錯誤以便正確處理
+  if (geminiResult.requestStatus === RequestStatus.FAILED) {
+    logger.error('[TEST] Gemini 生成失敗', {
+      errorCode: geminiResult.errorCode,
+      error: geminiResult.error,
+      errorContext: geminiResult.errorContext
+    });
+    const error = new Error(
+      geminiResult.errorCode || geminiResult.error || 'Generation failed'
+    ) as Error & {
+      errorCode?: string;
+      errorContext?: Record<string, string | number | boolean>;
+    };
+    error.errorCode = geminiResult.errorCode;
+    error.errorContext = geminiResult.errorContext;
+    throw error;
+  }
+
+  logger.info('[TEST] imageGenGemini 完成', {
+    id: geminiResult.id,
+    requestStatus: geminiResult.requestStatus
+  });
+
+  // 獲取完整的 ImageGeneration 記錄以返回預期格式
+  // 注意：triggerBackgroundProcessing 是異步執行的，所以資料庫可能還沒更新
+  // 但我們使用 geminiResult.requestStatus 來判斷實際狀態
+  const imageGeneration = await getImageGenerationById(geminiResult.id);
+  if (!imageGeneration) {
+    throw new Error('Failed to fetch image generation after creation');
+  }
+
+  // 如果 geminiResult 顯示已完成，但資料庫還是 PENDING，我們需要等待一下
+  // 或者直接使用 geminiResult 的狀態來構建返回對象
+  // 為了確保狀態一致，我們使用 geminiResult 的狀態
+  const finalImageGeneration: ImageGenerationWithOutputUrl = {
+    ...imageGeneration,
+    requestStatus: geminiResult.requestStatus as RequestStatus
+  };
+
+  logger.info('[TEST] generateIllustrationWithGemini 完成', {
+    imageGenerationId: finalImageGeneration.id,
+    requestStatus: finalImageGeneration.requestStatus
+  });
+  return finalImageGeneration;
+}
+
+/**
+ * Illustration 模式圖像生成的統一入口函數
+ *
+ * 此函數：
+ * 1. 統一檢查用戶禁用狀態
+ * 2. 處理 inputImage
+ * 3. 根據 baseModel 分流到 Gemini 或 ComfyUI 流程
+ * 4. 執行生成並建立記錄
+ *
+ * @param payload - 圖像生成所需的數據
+ * @returns 創建的 ImageGeneration 記錄
+ */
+export async function startIllustrationImageGeneration(
+  payload: ImageGenerationData
+): Promise<ImageGenerationWithOutputUrl> {
+  logger.info('[TEST] startIllustrationImageGeneration 開始', {
+    baseModel: payload.baseModel,
+    hasInputImage: !!payload.inputImage,
+    inputImageId: payload.inputImageId
+  });
+  // 統一檢查：禁用狀態
+  logger.info('[TEST] 檢查用戶禁用狀態');
+  await validateIllustrationGeneration();
+  logger.info('[TEST] 用戶禁用狀態檢查通過');
+
+  // 處理 inputImage
+  logger.info('[TEST] 處理 inputImage');
+  const inputImage = await processInputImageForIllustration(payload);
+  logger.info('[TEST] inputImage 處理完成', {
+    inputImageId: inputImage?.id
+  });
+
+  // 根據 baseModel 分流
+  if (payload.baseModel && isGeminiModel(payload.baseModel)) {
+    // Gemini 模型 → 調用 Gemini 生成流程
+    logger.info('[TEST] 檢測到 Gemini 模型，分流到 Gemini 流程', {
+      baseModel: payload.baseModel
+    });
+    return await generateIllustrationWithGemini(payload, inputImage);
+  } else {
+    // ComfyUI 模型 → 調用 ComfyUI 生成流程
+    logger.info('[TEST] 檢測到 ComfyUI 模型，分流到 ComfyUI 流程', {
+      baseModel: payload.baseModel
+    });
+    return await generateWithComfyUI(payload, inputImage);
+  }
+}
